provider "aws" {
  alias  = "controltower_aws"
  region = "us-east-1"
  assume_role {
    role_arn     = "arn:aws:iam::${var.control_tower_account}:role/cspm"
    session_name = "codebuild"
  }
}

provider "aws" {
  alias  = "audit_securityhub"
  region = "us-east-1"
  assume_role {
    role_arn     = "arn:aws:iam::${var.audit_account_id}:role/ResearchAdminRole"
    session_name = "codebuild"
    external_id  = var.cspm_external_id
  }
}
